/bin/bash -lc "node <<'NODE'
const assert = require('node:assert/strict');
const { merge_intervals } = require('./logic');
const input = Object.freeze([
  Object.freeze([10, 12]), Object.freeze([2, 7]),
  Object.freeze([1, 3]), Object.freeze([3, 3]),
  Object.freeze([7, 8]), Object.freeze([10, 12]),
  Object.freeze([9, 9])
]);
assert.deepEqual(merge_intervals(input), [[1, 8], [9, 9], [10, 12]]);
const single = [[2, 2]];
const result = merge_intervals(single);
assert.deepEqual(result, [[2, 2]]);
result[0][1] = 5;
assert.deepEqual(single, [[2, 2]]);
console.log('Additional interval and immutability checks passed.');
NODE
"

